"use client";

import { createClient } from "@/lib/supabase/client";
import type { Announcement, Category, Profile, Resource, TimetableEntry, TimetableKind } from "@/lib/types";
import { useMutation, useQueryClient, QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { Bell, BookOpen, CalendarDays, Clock, Download, FileText, FolderOpen, Heart, Home, LayoutDashboard, List, LogOut, MapPin, Megaphone, Menu, Pencil, Plus, Search, Trash2, Upload, User, X } from "lucide-react";
import { useRouter } from "next/navigation";
import { FormEvent, useMemo, useState } from "react";

const categories: Category[] = ["Lecture Notes", "Past Questions", "Assignments"];
const nav = [{ id: "home", label: "Home", icon: Home }, { id: "resources", label: "Resources", icon: FolderOpen }, { id: "favorites", label: "Favorites", icon: Heart }, { id: "announcements", label: "Announcements", icon: Bell }, { id: "timetable", label: "Timetable", icon: CalendarDays }, { id: "profile", label: "Profile", icon: User }];

export function Dashboard(props: { profile: Profile; initialResources: Resource[]; initialAnnouncements: Announcement[]; initialFavorites: string[]; initialTimetable: TimetableEntry[] }) {
  const [client] = useState(() => new QueryClient());
  return <QueryClientProvider client={client}><DashboardInner {...props}/></QueryClientProvider>;
}

function DashboardInner({ profile, initialResources, initialAnnouncements, initialFavorites, initialTimetable }: { profile: Profile; initialResources: Resource[]; initialAnnouncements: Announcement[]; initialFavorites: string[]; initialTimetable: TimetableEntry[] }) {
  const router = useRouter(); const queryClient = useQueryClient(); const supabase = createClient();
  const [page, setPage] = useState("home"); const [menu, setMenu] = useState(false); const [query, setQuery] = useState(""); const [category, setCategory] = useState("All");
  const [resources, setResources] = useState(initialResources); const [announcements, setAnnouncements] = useState(initialAnnouncements); const [timetable, setTimetable] = useState(initialTimetable); const [favorites, setFavorites] = useState(new Set(initialFavorites)); const [modal, setModal] = useState<"resource" | "announcement" | "timetable" | null>(null); const [editing, setEditing] = useState<Resource | null>(null); const [notice, setNotice] = useState("");
  const filtered = useMemo(() => resources.filter(r => `${r.title} ${r.course_code} ${r.course_name} ${r.department}`.toLowerCase().includes(query.toLowerCase()) && (category === "All" || r.category === category) && (page !== "favorites" || favorites.has(r.id))), [resources, query, category, page, favorites]);
  const flash = (text: string) => { setNotice(text); setTimeout(() => setNotice(""), 2500); };
  const favorite = useMutation({ mutationFn: async (r: Resource) => { if (favorites.has(r.id)) { const { error } = await supabase.from("favorites").delete().eq("user_id", profile.id).eq("resource_id", r.id); if (error) throw error; } else { const { error } = await supabase.from("favorites").insert({ user_id: profile.id, resource_id: r.id }); if (error) throw error; } }, onSuccess: (_, r) => { setFavorites(old => { const n = new Set(old); if (n.has(r.id)) n.delete(r.id); else n.add(r.id); return n; }); queryClient.invalidateQueries(); } });
  async function download(r: Resource) { const { data, error } = await supabase.storage.from("resources").createSignedUrl(r.storage_path, 60); if (error) return flash(error.message); await supabase.rpc("increment_download", { resource_id: r.id }); if (data?.signedUrl) window.open(data.signedUrl, "_blank", "noopener,noreferrer"); setResources(x => x.map(v => v.id === r.id ? { ...v, downloads: v.downloads + 1 } : v)); }
  async function remove(r: Resource) { if (!confirm(`Delete ${r.title}?`)) return; const { error } = await supabase.from("resources").delete().eq("id", r.id); if (error) return flash(error.message); await supabase.storage.from("resources").remove([r.storage_path]); setResources(x => x.filter(v => v.id !== r.id)); flash("Resource deleted."); }
  async function removeTimetable(entry: TimetableEntry) { if (!confirm(`Delete ${entry.course_name} from the timetable?`)) return; const { error } = await supabase.from("timetable_entries").delete().eq("id", entry.id); if (error) return flash(error.message); setTimetable(items => items.filter(item => item.id !== entry.id)); flash("Timetable entry deleted."); }
  async function signOut() { await supabase.auth.signOut(); router.push("/login"); router.refresh(); }
  const title = page === "home" ? `Hi, ${profile.full_name.split(" ")[0]}` : page[0].toUpperCase() + page.slice(1);
  return <div className="app-shell"><aside className={menu ? "sidebar open" : "sidebar"}><div className="app-brand"><span><BookOpen/></span><b>Easy</b><button onClick={() => setMenu(false)}><X/></button></div><div className="role-label">{profile.role === "course_rep" ? "COURSE REP PORTAL" : "STUDENT PORTAL"}</div><nav>{nav.map(n => <button key={n.id} className={page === n.id ? "active" : ""} onClick={() => { setPage(n.id); setMenu(false); }}><n.icon/>{n.label}</button>)}{profile.role === "course_rep" && <button className={page === "manage" ? "active" : ""} onClick={() => { setPage("manage"); setMenu(false); }}><LayoutDashboard/>Manage content</button>}</nav><div className="sidebar-user"><span>{profile.full_name.split(" ").map(x => x[0]).slice(0,2).join("")}</span><div><b>{profile.full_name}</b><small>{profile.role === "course_rep" ? "Course Representative" : "Student"} · Level {profile.level}</small></div><button onClick={signOut} title="Sign out"><LogOut/></button></div></aside>{menu && <button className="backdrop" onClick={() => setMenu(false)}/>}<main className="app-main"><header className="app-header"><button className="menu-btn" onClick={() => setMenu(true)}><Menu/></button><div className="global-search"><Search/><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Search courses, resources, departments..."/></div><button className="icon-button"><Bell/><i/></button><span className="top-avatar">{profile.full_name[0]}</span></header><div className="content"><div className="content-title"><div><h1>{title}</h1><p>{page === "home" ? "Here’s what’s happening with your courses." : page === "manage" ? "Upload and manage academic content." : `Manage your ${page}.`}</p></div>{profile.role === "course_rep" && page === "manage" && <div className="title-actions"><button className="secondary-action" onClick={() => setModal("timetable")}><CalendarDays/>Add timetable</button><button className="secondary-action" onClick={() => setModal("announcement")}><Megaphone/>Post announcement</button><button className="primary-action" onClick={() => { setEditing(null); setModal("resource"); }}><Plus/>Upload resource</button></div>}</div>{page === "home" && <HomeView resources={resources} announcements={announcements} favorites={favorites.size} downloads={resources.reduce((s,r)=>s+r.downloads,0)} rep={profile.role === "course_rep"} go={setPage}/>} {(page === "resources" || page === "favorites") && <ResourceView resources={filtered} favorites={favorites} category={category} setCategory={setCategory} onFavorite={r => favorite.mutate(r)} onDownload={download}/>} {page === "announcements" && <AnnouncementView announcements={announcements}/>} {page === "timetable" && <TimetableView entries={timetable} canManage={profile.role === "course_rep"} onDelete={removeTimetable}/>} {page === "profile" && <ProfileView profile={profile} onSaved={() => flash("Profile updated.")}/>} {page === "manage" && <ManageView resources={filtered} onEdit={r => { setEditing(r); setModal("resource"); }} onDelete={remove}/>}</div></main>{modal === "resource" && <ResourceModal profile={profile} resource={editing} onClose={() => setModal(null)} onSaved={r => { setResources(old => editing ? old.map(x => x.id === r.id ? r : x) : [r, ...old]); setModal(null); flash(editing ? "Resource updated." : "Resource uploaded."); }}/>} {modal === "announcement" && <AnnouncementModal profile={profile} onClose={() => setModal(null)} onSaved={a => { setAnnouncements(x => [a, ...x]); setModal(null); flash("Announcement posted."); }}/>} {modal === "timetable" && <TimetableModal profile={profile} onClose={() => setModal(null)} onSaved={entry => { setTimetable(x => [...x, entry]); setModal(null); flash("Timetable entry added."); }}/>} {notice && <div className="notice">{notice}</div>}</div>;
}

function HomeView({ resources, announcements, favorites, downloads, rep, go }: { resources: Resource[]; announcements: Announcement[]; favorites: number; downloads: number; rep: boolean; go: (p:string)=>void }) { return <><div className="stats-grid"><Stat icon={<FolderOpen/>} label="Resources" value={resources.length}/><Stat icon={<Heart/>} label="Favorites" value={favorites}/><Stat icon={<Download/>} label="Downloads" value={downloads}/><Stat icon={<Megaphone/>} label="Announcements" value={announcements.length}/></div><div className="dashboard-grid"><section><div className="section-head"><h2>Latest resources</h2><button onClick={()=>go("resources")}>View all</button></div><div className="compact-list">{resources.slice(0,5).map(r=><div key={r.id}><span className="file-icon"><FileText/></span><div><b>{r.title}</b><small>{r.course_code} · {r.category}</small></div><time>{new Date(r.created_at).toLocaleDateString()}</time></div>)}{!resources.length&&<Empty text="No resources have been uploaded yet."/>}</div></section><section><div className="section-head"><h2>Recent announcements</h2><button onClick={()=>go("announcements")}>View all</button></div><div className="announcement-mini">{announcements.slice(0,3).map(a=><article key={a.id}><Megaphone/><div><b>{a.title}</b><p>{a.message}</p><small>{new Date(a.created_at).toLocaleDateString()}</small></div></article>)}{!announcements.length&&<Empty text="No announcements yet."/>}</div></section></div>{rep&&<div className="rep-banner"><div><b>Course Representative tools</b><p>Upload materials, post updates, and monitor engagement.</p></div><button onClick={()=>go("manage")}>Open management</button></div>}</> }
function Stat({icon,label,value}:{icon:React.ReactNode;label:string;value:number}){return <article className="stat-card"><span>{icon}</span><div><small>{label}</small><b>{value}</b></div></article>}
function ResourceView({resources,favorites,category,setCategory,onFavorite,onDownload}:{resources:Resource[];favorites:Set<string>;category:string;setCategory:(x:string)=>void;onFavorite:(r:Resource)=>void;onDownload:(r:Resource)=>void}){return <><div className="category-row">{["All",...categories].map(c=><button key={c} className={category===c?"active":""} onClick={()=>setCategory(c)}>{c}</button>)}</div><div className="resource-grid">{resources.map(r=><article className="resource-card" key={r.id}><div className="resource-top"><span><FileText/></span><button className={favorites.has(r.id)?"liked":""} onClick={()=>onFavorite(r)}><Heart fill={favorites.has(r.id)?"currentColor":"none"}/></button></div><span className="category-badge">{r.category}</span><h3>{r.title}</h3><p>{r.description||"Academic resource for this course."}</p><div className="course-line"><b>{r.course_code}</b><span>{r.course_name}</span></div><footer><small><Download/> {r.downloads} downloads</small><button onClick={()=>onDownload(r)}>Download</button></footer></article>)}{!resources.length&&<Empty text="No resources match your search."/>}</div></>}
function AnnouncementView({announcements}:{announcements:Announcement[]}){return <div className="announcement-list">{announcements.map(a=><article key={a.id}><span><Megaphone/></span><div><h3>{a.title}</h3><p>{a.message}</p><small>{new Date(a.created_at).toLocaleString()}</small></div></article>)}{!announcements.length&&<Empty text="No announcements have been posted."/>}</div>}
function ManageView({resources,onEdit,onDelete}:{resources:Resource[];onEdit:(r:Resource)=>void;onDelete:(r:Resource)=>void}){return <div className="manage-card"><div className="manage-head"><h2>Your resource library</h2><span>{resources.length} resources</span></div><div className="resource-table">{resources.map(r=><div key={r.id}><span className="file-icon"><FileText/></span><div><b>{r.title}</b><small>{r.course_code} · {r.category}</small></div><span>{r.downloads} downloads</span><time>{new Date(r.created_at).toLocaleDateString()}</time><div><button onClick={()=>onEdit(r)}><Pencil/></button><button className="danger" onClick={()=>onDelete(r)}><Trash2/></button></div></div>)}{!resources.length&&<Empty text="Upload your first academic resource."/>}</div></div>}
const weekDays = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
function TimetableView({entries,canManage,onDelete}:{entries:TimetableEntry[];canManage:boolean;onDelete:(entry:TimetableEntry)=>void}){const[mode,setMode]=useState<"week"|"list">("week");const[section,setSection]=useState<TimetableKind>("class");const visible=entries.filter(entry=>entry.kind===section).sort((a,b)=>section==="class"?(a.day_of_week??0)-(b.day_of_week??0)||a.start_time.localeCompare(b.start_time):(a.exam_date||"").localeCompare(b.exam_date||"")||a.start_time.localeCompare(b.start_time));return <><div className="timetable-controls"><div><button className={section==="class"?"active":""} onClick={()=>setSection("class")}>Weekly classes</button><button className={section==="exam"?"active":""} onClick={()=>setSection("exam")}>Exams</button></div><div><button className={mode==="week"?"active":""} onClick={()=>setMode("week")}><CalendarDays/>Week</button><button className={mode==="list"?"active":""} onClick={()=>setMode("list")}><List/>List</button></div></div>{mode==="week"&&section==="class"?<div className="week-grid">{weekDays.map((day,index)=><section key={day}><h3>{day.slice(0,3)}</h3>{visible.filter(entry=>entry.day_of_week===index+1).map(entry=><TimetableCard key={entry.id} entry={entry} canManage={canManage} onDelete={onDelete}/>)}</section>)}</div>:<div className="timetable-list">{visible.map(entry=><div key={entry.id} className="schedule-row"><div className="schedule-date">{entry.kind==="class"?weekDays[(entry.day_of_week||1)-1]:new Date(`${entry.exam_date}T00:00:00`).toLocaleDateString(undefined,{month:"short",day:"numeric"})}</div><TimetableCard entry={entry} canManage={canManage} onDelete={onDelete}/></div>)}</div>}{!visible.length&&<Empty text={section==="class"?"No weekly classes have been added.":"No examinations have been scheduled."}/>}</>}
function TimetableCard({entry,canManage,onDelete}:{entry:TimetableEntry;canManage:boolean;onDelete:(entry:TimetableEntry)=>void}){return <article className="timetable-card"><div><b>{entry.course_code}</b><h4>{entry.course_name}</h4></div><p><Clock/>{entry.start_time.slice(0,5)} – {entry.end_time.slice(0,5)}</p><p><MapPin/>{entry.venue||"Venue not set"}</p>{entry.lecturer&&<small>{entry.lecturer}</small>}{canManage&&<button className="schedule-delete" onClick={()=>onDelete(entry)} title="Delete entry"><Trash2/></button>}</article>}
function TimetableModal({profile,onClose,onSaved}:{profile:Profile;onClose:()=>void;onSaved:(entry:TimetableEntry)=>void}){const supabase=createClient();const[kind,setKind]=useState<TimetableKind>("class");const[error,setError]=useState("");async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);const row={kind,course_code:f.get("courseCode"),course_name:f.get("courseName"),department:profile.department,level:profile.level,day_of_week:kind==="class"?Number(f.get("day")):null,exam_date:kind==="exam"?f.get("examDate"):null,start_time:f.get("startTime"),end_time:f.get("endTime"),venue:f.get("venue"),lecturer:f.get("lecturer"),created_by:profile.id};const{data,error}=await supabase.from("timetable_entries").insert(row).select().single();if(error)setError(error.message);else onSaved(data)}return <Modal title="Add timetable entry" onClose={onClose}><form className="modal-form" onSubmit={submit}><div className="role-picker"><button type="button" className={kind==="class"?"selected":""} onClick={()=>setKind("class")}>Weekly class</button><button type="button" className={kind==="exam"?"selected":""} onClick={()=>setKind("exam")}>Exam</button></div><div className="form-row"><label>Course code<input name="courseCode" required placeholder="CS 201"/></label><label>Course name<input name="courseName" required/></label></div>{kind==="class"?<label>Day<select name="day" required>{weekDays.map((day,index)=><option value={index+1} key={day}>{day}</option>)}</select></label>:<label>Exam date<input name="examDate" type="date" required/></label>}<div className="form-row"><label>Start time<input name="startTime" type="time" required/></label><label>End time<input name="endTime" type="time" required/></label></div><div className="form-row"><label>Venue<input name="venue" required/></label><label>Lecturer<input name="lecturer"/></label></div><label>Audience<input value={`${profile.department} · Level ${profile.level}`} disabled readOnly/></label>{error&&<p className="form-alert error">{error}</p>}<button className="primary-action"><CalendarDays/>Add to timetable</button></form></Modal>}
function ProfileView({profile,onSaved}:{profile:Profile;onSaved:()=>void}){const supabase=createClient();async function save(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);const{error}=await supabase.from("profiles").update({full_name:f.get("fullName"),student_id:f.get("studentId")}).eq("id",profile.id);if(!error)onSaved()}return <form className="profile-card" onSubmit={save}><div className="profile-avatar">{profile.full_name[0]}</div><h2>Personal information</h2><div className="form-grid"><label>Full name<input name="fullName" defaultValue={profile.full_name}/></label><label>Student ID<input name="studentId" defaultValue={profile.student_id}/></label><label>Email<input value={profile.email} disabled readOnly/></label><label>Department<input value={profile.department} disabled readOnly/></label><label>Level<input value={`Level ${profile.level}`} disabled readOnly/></label><label>Account type<input value={profile.role==="course_rep"?"Course Representative":"Student"} disabled readOnly/></label></div><button className="primary-action">Save changes</button></form>}
function ResourceModal({profile,resource,onClose,onSaved}:{profile:Profile;resource:Resource|null;onClose:()=>void;onSaved:(r:Resource)=>void}){const supabase=createClient();const[busy,setBusy]=useState(false);const[error,setError]=useState("");async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setError("");const f=new FormData(e.currentTarget);try{let path=resource?.storage_path||"";const file=f.get("file") as File;if(file?.size){const ext=file.name.split(".").pop()?.toLowerCase();if(!["pdf","docx","pptx","zip"].includes(ext||""))throw new Error("Only PDF, DOCX, PPTX, and ZIP files are allowed.");path=`${profile.id}/${crypto.randomUUID()}.${ext}`;const{error}=await supabase.storage.from("resources").upload(path,file);if(error)throw error}if(!path)throw new Error("Choose a file.");const row={title:f.get("title"),description:f.get("description"),course_code:f.get("courseCode"),course_name:f.get("courseName"),department:profile.department,level:profile.level,category:f.get("category"),file_url:path,storage_path:path,uploaded_by:profile.id};const result=resource?await supabase.from("resources").update(row).eq("id",resource.id).select().single():await supabase.from("resources").insert(row).select().single();if(result.error)throw result.error;onSaved(result.data)}catch(err){setError(err instanceof Error?err.message:"Upload failed.")}finally{setBusy(false)}}return <Modal title={resource?"Edit resource":"Upload resource"} onClose={onClose}><form className="modal-form" onSubmit={submit}><label>Resource title<input name="title" required defaultValue={resource?.title}/></label><label>Description<textarea name="description" defaultValue={resource?.description}/></label><div className="form-row"><label>Course code<input name="courseCode" required defaultValue={resource?.course_code}/></label><label>Course name<input name="courseName" required defaultValue={resource?.course_name}/></label></div><div className="form-row"><label>Department and level<input value={`${profile.department} · Level ${profile.level}`} disabled readOnly/></label><label>Category<select name="category" defaultValue={resource?.category}>{categories.map(c=><option key={c}>{c}</option>)}</select></label></div><label>File (PDF, DOCX, PPTX, ZIP)<input name="file" type="file" required={!resource} accept=".pdf,.docx,.pptx,.zip"/></label>{error&&<p className="form-alert error">{error}</p>}<button className="primary-action" disabled={busy}><Upload/>{busy?"Saving...":"Save resource"}</button></form></Modal>}
function AnnouncementModal({profile,onClose,onSaved}:{profile:Profile;onClose:()=>void;onSaved:(a:Announcement)=>void}){const supabase=createClient();const[error,setError]=useState("");async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);const{data,error}=await supabase.from("announcements").insert({title:f.get("title"),message:f.get("message"),created_by:profile.id,department:profile.department,level:profile.level}).select().single();if(error)setError(error.message);else onSaved(data)}return <Modal title="Post announcement" onClose={onClose}><form className="modal-form" onSubmit={submit}><label>Title<input name="title" required/></label><label>Message<textarea name="message" required rows={6}/></label>{error&&<p className="form-alert error">{error}</p>}<button className="primary-action"><Megaphone/>Post announcement</button></form></Modal>}
function Modal({title,onClose,children}:{title:string;onClose:()=>void;children:React.ReactNode}){return <div className="modal-wrap"><button className="modal-shade" onClick={onClose}/><section className="modal"><header><h2>{title}</h2><button onClick={onClose}><X/></button></header>{children}</section></div>}
function Empty({text}:{text:string}){return <div className="empty"><FolderOpen/><b>{text}</b><small>Content will appear here when available.</small></div>}
